:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --font: 'Courier New', Courier, monospace, system-ui, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.04) 1px, transparent 0);
  background-size: 16px 16px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
  padding: 24px;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  line-height: 1.3;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--muted);
  font-size: 0.95rem;
  margin-bottom: 20px;
}

.entry-form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

input[type="number"] {
  flex: 1 1 120px;
  min-width: 0;
  padding: 12px;
  font-family: var(--font);
  font-size: 1rem;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  outline: none;
  transition: border-color 0.15s;
}

input[type="number"]:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233,69,96,0.35);
}

input[type="number"]::placeholder {
  color: var(--muted);
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 16px;
  cursor: pointer;
  border: 3px solid #000;
  background: var(--accent);
  color: #fff;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #000;
}

.hint {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 8px;
}

.error {
  color: var(--accent-hover);
  font-size: 0.9rem;
  min-height: 1.2em;
  margin-top: 4px;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 20px 0;
}

.stat {
  background: var(--bg);
  border: 3px solid var(--border);
  padding: 12px 8px;
  text-align: center;
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--accent);
  word-break: break-all;
}

.list-title {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.readings-list {
  list-style: none;
  max-height: 180px;
  overflow-y: auto;
  border: 3px solid var(--border);
  background: var(--bg);
}

.readings-list:empty {
  display: none;
}

.readings-list li {
  padding: 8px 12px;
  border-bottom: 2px solid var(--border);
  font-size: 1rem;
}

.readings-list li:last-child {
  border-bottom: none;
}

.readings-list li::before {
  content: "\25B8 ";
  color: var(--accent);
}

.empty {
  color: var(--muted);
  font-size: 0.9rem;
  padding: 12px;
  border: 3px dashed var(--border);
  text-align: center;
}

.clear-btn {
  width: 100%;
  margin-top: 20px;
  background: var(--border);
}

.clear-btn:hover {
  background: #1b4a7a;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .stat-value {
    font-size: 1.1rem;
  }
}

(function () {
  'use strict';

  var readings = [];

  var form = document.getElementById('entry-form');
  var input = document.getElementById('temp-input');
  var errorMsg = document.getElementById('error-msg');
  var list = document.getElementById('readings-list');
  var emptyMsg = document.getElementById('empty-msg');
  var statMin = document.getElementById('stat-min');
  var statMax = document.getElementById('stat-max');
  var statAvg = document.getElementById('stat-avg');
  var clearBtn = document.getElementById('clear-btn');

  function format(n) {
    return (Math.round(n * 10) / 10).toString() + ' \u00B0C';
  }

  function render() {
    // List
    list.innerHTML = '';
    for (var i = 0; i < readings.length; i++) {
      var li = document.createElement('li');
      li.textContent = format(readings[i]);
      list.appendChild(li);
    }
    emptyMsg.hidden = readings.length > 0;

    // Stats
    if (readings.length === 0) {
      statMin.textContent = '\u2014';
      statMax.textContent = '\u2014';
      statAvg.textContent = '\u2014';
      return;
    }

    var min = readings[0];
    var max = readings[0];
    var sum = 0;
    for (var j = 0; j < readings.length; j++) {
      var v = readings[j];
      if (v < min) min = v;
      if (v > max) max = v;
      sum += v;
    }
    statMin.textContent = format(min);
    statMax.textContent = format(max);
    statAvg.textContent = format(sum / readings.length);
  }

  function showError(msg) {
    errorMsg.textContent = msg;
  }

  function clearError() {
    errorMsg.textContent = '';
  }

  function addReading() {
    clearError();

    var raw = input.value.trim();
    if (raw === '') {
      showError('Please enter a temperature.');
      input.focus();
      return;
    }

    var value = Number(raw);
    if (!isFinite(value)) {
      showError('Please enter a valid number.');
      input.focus();
      return;
    }

    readings.push(value);
    input.value = '';
    input.focus();
    render();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    addReading();
  });

  // Explicit Enter key handler on the input as a fallback for browsers
  // that do not submit the form when Enter is pressed in a number input.
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      addReading();
    }
  });

  clearBtn.addEventListener('click', function () {
    readings = [];
    clearError();
    render();
    input.focus();
  });

  input.addEventListener('input', clearError);

  render();
})();
